model:
rachana: 1
sutra: residue
version: 1
description: 
match: { kind: residue, priority: 10 }
title: { pill: "Protein engineering · Residue", id: "$.RESIDUE_ID" }
strip:
  - { label: "Residue id", bind: "$.RESIDUE_ID" }
  - { label: "Aa", bind: "$.AA" }
  - { label: "Secondary", bind: "$.SECONDARY" }
  - { label: "Domain", bind: "$.DOMAIN" }
  - { label: "Burial", bind: "$.BURIAL", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Residue"
    columns:
      - { label: "Residue id", bind: "$.RESIDUE_ID" }
      - { label: "Protein", bind: "link($.PROTEIN, 'protein')" }
      - { label: "Pos", bind: "$.POS", fmt: "amount0" }
      - { label: "Aa", bind: "$.AA" }
      - { label: "Secondary", bind: "$.SECONDARY" }
      - { label: "Domain", bind: "$.DOMAIN" }
      - { label: "Burial", bind: "$.BURIAL" }
      - { label: "Active site", bind: "$.ACTIVE_SITE" }
      - { label: "X", bind: "$.X" }
      - { label: "Y", bind: "$.Y" }
      - { label: "Z", bind: "$.Z" }
      - { label: "Mean activity", bind: "$.MEAN_ACTIVITY" }
      - { label: "Mean stability", bind: "$.MEAN_STABILITY" }
keys: { F9: "raw" }
